export class RankingClient{
 constructor({endpoint='/api/ranking',gas=false,fetcher=globalThis.fetch?.bind(globalThis),storage,timeout=gas?15000:5000}={}){this.endpoint=endpoint;this.gas=gas;this.fetcher=fetcher;this.storage=storage;this.timeout=timeout;this.profile=null;this.token=null;try{this.storage??=globalThis.localStorage;if(gas)this.token=this.storage.getItem('high-low:ranking-token:v1')}catch{}}
 async call(action,data={}){if(!this.fetcher||!/^https?:$/.test(globalThis.location?.protocol||'http:'))throw Error('オンラインランキングはWeb配信版で利用できます。');const controller=new AbortController();let timer;try{const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>{controller.abort();reject(Error('通信がタイムアウトしました。再試行してください。'))},this.timeout)});const operation=(async()=>{const response=await this.fetcher(this.endpoint,{method:'POST',credentials:this.gas?'omit':'same-origin',headers:{'content-type':this.gas?'text/plain;charset=utf-8':'application/json'},body:JSON.stringify({action,data,...(this.gas?{token:this.token}: {})}),signal:controller.signal});let value;try{value=await response.json()}catch{throw Error('ランキングAPIの応答を確認できません。')}if(!response.ok||value.error){if(value.error?.code==='UNAUTHORIZED'){this.profile=null;this.token=null;try{this.storage?.removeItem('high-low:ranking-token:v1')}catch{}}throw Error(value.error?.message||'ランキングの通信に失敗しました。');}if(value.token){this.token=value.token;try{this.storage.setItem('high-low:ranking-token:v1',value.token)}catch{throw Error('プレイヤー識別情報を保存できません。ブラウザの保存設定をご確認ください。')}}return value})();return await Promise.race([operation,timeout])}catch(e){if(e.name==='AbortError')throw Error('通信がタイムアウトしました。再試行してください。');throw e}finally{clearTimeout(timer)}}
 async identity(){if(this.profile)return this.profile;if(!this.identityRequest)this.identityRequest=this.call('profile').then(p=>this.profile=p).finally(()=>{this.identityRequest=null});return this.identityRequest}
 async nickname(name){this.profile=await this.call('profile',{nickname:name});return this.profile}
 async start(difficulty){await this.identity();return this.call('start',{difficulty})}
 async ranking(difficulty,period){await this.identity();return this.call('ranking',{difficulty,period})}
 submit(runId,game){return this.call('submit',{runId,completed:true,answers:game.history.map(a=>({questionId:a.question.id,choice:a.choice,elapsed:a.elapsed}))})}
}
